mapper.select:
select count(1)
from sys_user_post
where user_id = #{userId} and company_id = #{orgId} and post_id = #{postId}

select userId, employeeId, name, gender, mobilePhone, workStatus, orgId, orgName, postGroupId, postGroupName, postId, postName from ( SELECT any_value(sup.user_id) AS userId, any_value(se.id) AS employeeId, any_value(se.`name`) AS `name`, any_value(se.gender) AS gender, any_value(se.mobile_phone) AS mobilePhone, any_value(se.work_status) AS workStatus, any_value(sup.company_id) AS orgId, any_value(IFNULL( cei.abbreviation, '公司' )) AS orgName, any_value(sup.group_id) AS postGroupId, any_value(pg.`name`) AS postGroupName, any_value(sup.post_id) AS postId, any_value(p.`name`) AS postName FROM sys_user_post sup LEFT JOIN sys_employee se ON sup.user_id = se.user_id LEFT JOIN clinic_ext_info cei ON sup.company_id = cei.company_id LEFT JOIN post_group pg ON sup.group_id = pg.id LEFT JOIN post p ON sup.post_id = p.id
and sup.user_id in
#{item}
and sup.company_id in
#{item}
and sup.group_id in
#{item}
and sup.post_id in
#{item}
group by sup.user_id ) sup
and sup.workStatus in
#{item}
order by case when workStatus = 2 then 2 else 1 end, convert(sup.name using gbk)
